// # Safety
//
// `world` is null or live; `ray` is null or readable; `out` is null or
// writable.
FyStatus fy_raycast(const struct FyWorld *world,
                    const struct FyRay *ray,
                    float max_distance,
                    uint32_t mask,
                    struct FyRayHit *out);

